        (int)C, N * HW,
        (float)eps, (float)momentum);
    bn2d_normalize_kernel<Threads><<<dim3((unsigned)C, (unsigned)tiles), dim3(Threads), 0, stream>>>(
        x_c.data_ptr<float>(),
